mapper.select:
select v.id, i.flow_key as flowKey, i.flow_type as flowType, i.flow_name as flowName, v.flow_version_status as flowVersionStatus, v.flow_content as flowContent, v.inputs as inputs, v.outputs as outputs, v.variables as variables from t_flow_info i left join t_flow_version v on i.id=v.flow_id where 1=1 and v.deleted = 0
and i.flow_key = #{flowKey}
and v.flow_version = #{flowVersion}

select v.id, i.flow_key as flowKey, i.flow_name as flowName, v.flow_version as flowVersion, v.flow_version_status as flowVersionStatus, v.flow_version_remark as flowVersionRemark, v.app_code as appCode from t_flow_info i left join t_flow_version v on i.id=v.flow_id where 1=1 and v.deleted = 0
and flow_id = #{flowId}
and v.flow_version_status = #{flowVersionStatus}
and v.flow_name like concat("%", #{flowName}, "%")
and v.flow_key = #{flowKey}
and v.app_code = #{appCode}
order by v.id desc
